"""Write trigtable.go: sin, cos and atan at the grid points j/128 as
double-doubles, from mpmath at 300 bits.

    uv run --with mpmath==1.4.1 python testdata/gen/trigtable.py > trigtable.go
"""

import mpmath
from mpmath import mp, mpf

mp.prec = 300


def dd(v):
    hi = float(v)
    lo = float(v - mpf(hi))
    return "{%r, %r}" % (hi, lo)


def table(name, fn, n, doc):
    print("// %s" % doc)
    print("var %s = [%d]dd.DD{" % (name, n))
    for j in range(n):
        print("\t%s," % dd(fn(mpf(j) / 128)))
    print("}")
    print()


print("// Code generated by testdata/gen/trigtable.py from mpmath at 300 bits; DO NOT EDIT.")
print()
print("package stats")
print()
print('import "github.com/go-statistics/stats/internal/dd"')
print()
table("sinTable", mpmath.sin, 102, "sinTable[j] is sin(j/128), j/128 up to just past π/4.")
table("cosTable", mpmath.cos, 102, "cosTable[j] is cos(j/128).")
table("atanTable", mpmath.atan, 129, "atanTable[j] is atan(j/128) on [0, 1].")
for name, v in [("piDD", mpmath.pi), ("halfPiDD", mpmath.pi / 2), ("quarterPiDD", mpmath.pi / 4),
                ("invPiDD", 1 / mpmath.pi), ("twoPiDD", 2 * mpmath.pi), ("ln2DD", mpmath.log(2)),
                ("logPiDD", mpmath.log(mpmath.pi)), ("halfLogHalfPiDD", mpmath.log(mpmath.pi / 2) / 2),
                ("sqrt2DD", mpmath.sqrt(2)), ("invSqrt2DD", 1 / mpmath.sqrt(2)),
                ("twoOverSqrtPiDD", 2 / mpmath.sqrt(mpmath.pi)), ("log2PiDD", mpmath.log(2 * mpmath.pi)),
                ("eulerDD", mpmath.euler)]:
    print("var %s = dd.DD%s" % (name, dd(v)))
